const $=(s,c=document)=>c.querySelector(s), $$=(s,c=document)=>[...c.querySelectorAll(s)];
document.addEventListener('DOMContentLoaded',()=>{mountChrome();mountTitleField();mountLoader();document.body.classList.remove('loading');const h=$('.site-header'),t=$('.menu-toggle'),p=$('.scroll-progress');const onScroll=()=>{h?.classList.toggle('scrolled',scrollY>18);if(p){const max=document.documentElement.scrollHeight-innerHeight;p.style.width=`${max?scrollY/max*100:0}%`}};addEventListener('scroll',onScroll,{passive:true});onScroll();t?.addEventListener('click',()=>{const open=h.classList.toggle('open');t.setAttribute('aria-expanded',String(open))});$$('.nav a').forEach(a=>a.addEventListener('click',()=>h?.classList.remove('open')));const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');io.unobserve(e.target)}}),{threshold:.12});$$('.reveal').forEach(el=>io.observe(el));loadSettings();initField()});
function mountTitleField(){if($('#hero-canvas'))return;const host=$('.page-hero,.shop-hero,.not-found')||$('.article')?.parentElement;if(!host)return;const c=document.createElement('canvas');c.id='hero-canvas';c.setAttribute('aria-hidden','true');host.prepend(c);host.classList.add('has-webgl')}
function mountLoader(){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;const first=!sessionStorage.getItem('rs-visited');const loader=document.createElement('div');loader.className=`page-loader${first?'':' is-short'}`;loader.setAttribute('aria-hidden','true');loader.innerHTML='<div class="loader-inner"><div class="loader-brand"><strong>REALIZE SUMMIT.</strong><span>LOADING</span></div><div class="loader-track"><div class="loader-bar"></div></div><div class="loader-count">ASCEND / 2026</div></div>';document.body.append(loader);sessionStorage.setItem('rs-visited','1');setTimeout(()=>loader.classList.add('is-done'),first?2200:620);document.addEventListener('click',e=>{const a=e.target.closest('a');if(!a||a.target==='_blank'||a.hasAttribute('download')||a.href.startsWith('mailto:')||a.origin!==location.origin||(a.pathname===location.pathname&&a.search===location.search))return;e.preventDefault();loader.classList.remove('is-done','is-short');loader.classList.add('is-exit');setTimeout(()=>location.href=a.href,560)})}
function mountChrome(){const page=document.body.dataset.page||'';const links=[['home','index.html','HOME'],['about','about.html','ABOUT'],['news','news.html','NEWS'],['members','members.html','MEMBERS'],['sponsors','sponsors.html','SPONSORS'],['contact','contact.html','CONTACT'],['shop','shop.html','SHOP']];const mark='<span class="brand-mark"><img src="assets/images/rs-icon.png" alt="" width="38" height="38"></span>';const header=`<header class="site-header"><div class="scroll-progress"></div><div class="container header-inner"><a class="brand" href="index.html" aria-label="Realize Summit ホーム">${mark}<span>REALIZE SUMMIT</span></a><button class="menu-toggle" aria-label="メニューを開く" aria-expanded="false"><span></span><span></span></button><nav class="nav" aria-label="メインナビゲーション">${links.map(([id,href,label])=>`<a href="${href}" ${page===id?'aria-current="page"':''} class="${id==='shop'?'shop-link':''}">${label}</a>`).join('')}</nav></div></header>`;const footer=`<footer class="site-footer"><div class="container"><div class="footer-main"><a class="brand" href="index.html">${mark}<span>REALIZE SUMMIT</span></a><nav class="footer-links">${links.map(([,h,l])=>`<a href="${h}">${l}</a>`).join('')}</nav><div class="social-links"><a data-setting="x" href="#">X</a><a data-setting="youtube" href="#">YOUTUBE</a></div></div><div class="copyright"><span>© 2026 REALIZE SUMMIT.</span><span>ALL RIGHTS RESERVED.</span></div></div></footer>`;$('#site-header')?.replaceWith(document.createRange().createContextualFragment(header));$('#site-footer')?.replaceWith(document.createRange().createContextualFragment(footer))}
async function loadSettings(){try{const s=await fetch('data/settings.json').then(r=>r.json());$$('[data-setting]').forEach(el=>{const k=el.dataset.setting;if(s[k]){if(el.tagName==='A')el.href=s[k];else el.textContent=s[k]}})}catch{}}
function initField(){const c=$('#hero-canvas');if(!c)return;const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;const gl=c.getContext('webgl',{alpha:false,antialias:false,powerPreference:'high-performance'});if(!gl)return;const vs='attribute vec2 p;varying vec2 v;void main(){v=p*.5+.5;gl_Position=vec4(p,0.,1.);}';const fs=`precision mediump float;varying vec2 v;uniform vec2 r;uniform vec2 m;uniform float t;uniform float ready;uniform sampler2D icon;void main(){float aspect=r.x/r.y;vec2 uv=v;if(aspect>1.0)uv.y=(uv.y-.5)/aspect+.5;else uv.x=(uv.x-.5)*aspect+.5;vec2 q=v-.5;float pulse=.5+.5*sin(t*.7);float d=distance(q,m*.18);float influence=1.-smoothstep(.05,.65,d);float wave=sin(q.y*23.+t*1.15)+sin(q.x*17.-t*.85);vec2 warp=vec2(wave,sin((q.x+q.y)*29.-t))*mix(.002,.014,influence);vec2 tuv=clamp(uv+warp,0.,1.);float split=.0025+.0045*influence;vec3 tex=vec3(texture2D(icon,tuv+vec2(split,0.)).r,texture2D(icon,tuv).g,texture2D(icon,tuv-vec2(split,0.)).b);float scan=.93+.07*sin(gl_FragCoord.y*.72+t*4.);float grain=fract(sin(dot(gl_FragCoord.xy,vec2(12.9898,78.233))+t)*43758.5453);tex*=scan;vec2 u=(gl_FragCoord.xy-.5*r)/r.y;float field=(sin(u.x*1.7+u.y*.9+t*.18)+sin(u.x*.65-u.y*1.35-t*.14)*.7)/1.7;vec3 base=vec3(.008,.009,.011)+vec3(.22,.006,.014)*smoothstep(-.75,.8,field)*.42;float vign=1.-smoothstep(.42,1.28,length(u));float imageFade=smoothstep(.02,.32,max(max(tex.r,tex.g),tex.b));vec3 col=mix(base,tex*.48+base*.32,imageFade*ready*.92);col+=vec3(.22,.025,.035)*pulse*.035;col+=(grain-.5)*.018;col*=.56+.44*vign;gl_FragColor=vec4(col,1.);}`;function shader(type,src){const s=gl.createShader(type);gl.shaderSource(s,src);gl.compileShader(s);if(!gl.getShaderParameter(s,gl.COMPILE_STATUS)){console.warn(gl.getShaderInfoLog(s));return null}return s}const sv=shader(gl.VERTEX_SHADER,vs),sf=shader(gl.FRAGMENT_SHADER,fs);if(!sv||!sf)return;const pr=gl.createProgram();gl.attachShader(pr,sv);gl.attachShader(pr,sf);gl.linkProgram(pr);if(!gl.getProgramParameter(pr,gl.LINK_STATUS))return;gl.useProgram(pr);const b=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,b);gl.bufferData(gl.ARRAY_BUFFER,new Float32Array([-1,-1,3,-1,-1,3]),gl.STATIC_DRAW);const p=gl.getAttribLocation(pr,'p');gl.enableVertexAttribArray(p);gl.vertexAttribPointer(p,2,gl.FLOAT,false,0,0);const ur=gl.getUniformLocation(pr,'r'),um=gl.getUniformLocation(pr,'m'),ut=gl.getUniformLocation(pr,'t'),uready=gl.getUniformLocation(pr,'ready');const texture=gl.createTexture();gl.activeTexture(gl.TEXTURE0);gl.bindTexture(gl.TEXTURE_2D,texture);gl.texImage2D(gl.TEXTURE_2D,0,gl.RGBA,1,1,0,gl.RGBA,gl.UNSIGNED_BYTE,new Uint8Array([8,8,10,255]));gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_WRAP_S,gl.CLAMP_TO_EDGE);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_WRAP_T,gl.CLAMP_TO_EDGE);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MIN_FILTER,gl.LINEAR);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MAG_FILTER,gl.LINEAR);gl.uniform1i(gl.getUniformLocation(pr,'icon'),0);let imageReady=0;const image=new Image();image.decoding='async';image.onload=()=>{gl.bindTexture(gl.TEXTURE_2D,texture);gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL,true);gl.texImage2D(gl.TEXTURE_2D,0,gl.RGBA,gl.RGBA,gl.UNSIGNED_BYTE,image);imageReady=1};image.src='assets/images/rs-icon.png';let w=0,h=0,raf,mouse=[0,0],start=performance.now();function resize(){const d=Math.min(devicePixelRatio,innerWidth<700?1:1.5);w=c.width=Math.max(1,Math.floor(c.clientWidth*d));h=c.height=Math.max(1,Math.floor(c.clientHeight*d));gl.viewport(0,0,w,h)}function draw(now){gl.uniform2f(ur,w,h);gl.uniform2f(um,mouse[0],mouse[1]);gl.uniform1f(ut,reduced?0:(now-start)/1000);gl.uniform1f(uready,imageReady);gl.drawArrays(gl.TRIANGLES,0,3);if(!reduced)raf=requestAnimationFrame(draw)}addEventListener('resize',resize);if(!reduced)addEventListener('pointermove',e=>{const rect=c.getBoundingClientRect();mouse=[(e.clientX-rect.left)/Math.max(rect.width,1)-.5,.5-(e.clientY-rect.top)/Math.max(rect.height,1)]},{passive:true});document.addEventListener('visibilitychange',()=>{cancelAnimationFrame(raf);if(!document.hidden&&!reduced)raf=requestAnimationFrame(draw)});resize();raf=requestAnimationFrame(draw)}
